// @spec specs/hal-engine-config-hooks/spec.md#15
import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

it('reports turn-local totals across a missing tool round and resets for an unreported turn', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'first', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 3, outputTokens: 2, totalTokens: 5}},
    ],
    [
      {type: 'tool_use', toolCall: {id: 'second', name: 'lookup', input: {}}},
      {type: 'stop', stopReason: 'tool_use'},
    ],
    [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 4, totalTokens: 11}}],
    [{type: 'stop', stopReason: 'end_turn'}],
  ];
  const provider: AIProvider = {
    async *sendMessage() {
      yield* rounds.shift() ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      throw new Error('Structured generation is outside this streaming contract.');
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
  const reports: Array<UsageMetadata | undefined> = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage contract.'}), registry, {
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    },
  });

  for (const sessionId of ['reported', 'unreported']) {
    await orchestrator.processMessage({
      sessionId,
      userId: 'user',
      entries: [{role: 'user', content: 'Lookup', timestamp: '2026-01-01T00:00:00.000Z'}],
    });
  }

  expect(reports).toEqual([{inputTokens: 10, outputTokens: 6, totalTokens: 16}, undefined]);
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/turnUsageContract.test.ts --runInBand"
